package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8JsonGenerator.writeBoolean.
 * Maximizing branch and line coverage.
 */
public class UTF8JsonGenerator_writeBoolean_TriageGen1Test {

    private ByteArrayOutputStream out;
    private IOContext ioc;
    private ObjectCodec codec;

    @Before
    public void setUp() {
        out = new ByteArrayOutputStream();
        ioc = IOContext.bootstrap();
        codec = null; // Not strictly needed for this specific method call
    }

    @Test
    public void testWriteBooleanTrue() throws IOException {
        UTF8JsonGenerator gen = new UTF8JsonGenerator(ioc, 0, codec, out);
        gen.writeBoolean(true);
        gen.flush();

        // TRUE_BYTES is usually "true" in UTF-8
        byte[] expected = "true".getBytes();
        assertArrayEquals(expected, out.toByteArray());
    }

    @Test
    public void testWriteBooleanFalse() throws IOException {
        UTF8JsonGenerator gen = new UTF8JsonGenerator(ioc, 0, codec, out);
        gen.writeBoolean(false);
        gen.flush();

        // FALSE_BYTES is usually "false" in UTF-8
        byte[] expected = "false".getBytes();
        assertArrayEquals(expected, out.toByteArray());
    }

    @Test
    public void testWriteBooleanTriggersFlush() throws IOException {
        // To test the buffer flush logic: (_outputTail + 5) >= _outputEnd
        // We use the constructor that allows specifying a small buffer.
        // We provide a buffer of size 5.
        byte[] smallBuffer = new byte[5];

        // We need to ensure _outputTail is at a position where adding 4 or 5 bytes triggers the flush.
        // Since we can't easily set _outputTail via public API, we write something first.

        // Using a custom OutputStream to track calls might be hard, but we can observe the side effect.
        // If we write "true" (4 bytes) into a buffer of size 5, the next write should trigger flush.

        UTF8JsonGenerator gen = new UTF8JsonGenerator(ioc, 0, codec, out, smallBuffer, 0, false);

        // 1. Write 't' (1 byte). Tail becomes 1. (1+5) < 5 is false? 
        // Actually, the logic is: if (_outputTail + 5) >= _outputEnd
        // If buffer size is 5, _outputEnd is 5. 
        // If tail is 0: (0+5) >= 5 is TRUE. It flushes immediately.

        // Let's test the immediate flush scenario
        gen.writeBoolean(true); 
        // Because (0 + 5) >= 5, it flushes before writing. 
        // Then it writes "true" to the buffer.
        // We must call flush or close to see the content if it didn't trigger on the second write.

        gen.flush();
        assertArrayEquals("true".getBytes(), out.toByteArray());
    }

    @Test
    public void testWriteBooleanWithBufferBoundary() throws IOException {
        // Create a buffer where the tail is just before the threshold.
        // buffer size 10.
        byte[] buffer = new byte[10];
        UTF8JsonGenerator gen = new UTF8JsonGenerator(ioc, 0, codec, out, buffer, 0, false);

        // We need to fill the buffer up to a certain point.
        // Since we can't access _outputTail, we write something.
        // writeString("abc") -> tail is 3.
        gen.writeRaw("abc"); 

        // Now tail is 3. _outputEnd is 10.
        // (3 + 5) = 8. 8 < 10. No flush.
        gen.writeBoolean(true); // writes "true" (4 bytes)
        // tail becomes 3 + 4 = 7.

        // Next call: (7 + 5) = 12. 12 >= 10. TRIGGER FLUSH.
        gen.writeBoolean(false);

        gen.flush();

        // Expected: "abc" + "true" + "false"
        byte[] expected = "abctruefalse".getBytes();
        assertArrayEquals(expected, out.toByteArray());
    }

    @Test
    public void testWriteBooleanLargeBuffer() throws IOException {
        // Test that it works with a large buffer without flushing prematurely
        byte[] buffer = new byte[100];
        UTF8JsonGenerator gen = new UTF8JsonGenerator(ioc, 0, codec, out, buffer, 0, false);

        gen.writeBoolean(true);
        gen.writeBoolean(true);
        gen.writeBoolean(true);

        gen.flush();
        byte[] expected = "truetruetrue".getBytes();
        assertArrayEquals(expected, out.toByteArray());
    }
}
